<template><view class="page"><view class="card form"><picker :range="types" range-key="label" @change="typeIndex=Number($event.detail.value)"><view class="picker">申请类型：{{types[typeIndex].label}}</view></picker><picker :range="members" range-key="playerName" @change="selectMember"><view class="picker">涉及成员：{{selectedMember?.playerName||'请选择'}}</view></picker><picker v-if="type==='TRANSFER'" :range="targets" range-key="player_name" @change="targetIndex=Number($event.detail.value)"><view class="picker">接替陪玩：{{targets[targetIndex]?.player_name||'请选择'}}</view></picker><textarea v-model="reason" placeholder="请说明申请原因"/><button class="primary" @click="submit">提交平台审核</button></view></view></template>
<script setup lang="ts">import{computed,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{createCustomerServiceException,getCustomerOrder,getTransferTargets}from'@/api/customer';import type{RecordData}from'@/types/api';const id=ref(0),members=ref<RecordData[]>([]),memberIndex=ref(-1),targets=ref<RecordData[]>([]),targetIndex=ref(-1),typeIndex=ref(0),reason=ref('');const types=[{label:'申请转单',value:'TRANSFER'},{label:'申请炸单',value:'ABORT'}]as const;const type=computed(()=>types[typeIndex.value].value),selectedMember=computed(()=>members.value[memberIndex.value]);onLoad(async q=>{id.value=Number(q?.id);const d=await getCustomerOrder(id.value);members.value=((d.members as RecordData[])||[]).filter(x=>['ACCEPTED','IN_SERVICE'].includes(String(x.memberStatus)));});async function selectMember(e:any){memberIndex.value=Number(e.detail.value);targetIndex.value=-1;targets.value=type.value==='TRANSFER'?await getTransferTargets(id.value,Number(selectedMember.value?.id)):[]}async function submit(){if(!selectedMember.value)return uni.showToast({title:'请选择涉及成员',icon:'none'});if(type.value==='TRANSFER'&&!targets.value[targetIndex.value])return uni.showToast({title:'请选择接替陪玩',icon:'none'});if(!reason.value.trim())return uni.showToast({title:'请填写申请原因',icon:'none'});await createCustomerServiceException(id.value,{requestType:type.value,sourceOrderMemberId:Number(selectedMember.value.id),targetPlayerId:type.value==='TRANSFER'?Number(targets.value[targetIndex.value].player_id):undefined,reason:reason.value});uni.showToast({title:'已提交审核'});setTimeout(()=>uni.navigateBack(),500)}</script>
<style scoped>.form{display:flex;flex-direction:column;gap:24rpx}.picker,.form textarea{padding:22rpx;border-radius:16rpx;background:#f5f6f2}.form textarea{width:100%;height:240rpx;box-sizing:border-box}</style>
